const char* T(const char* ru) {
    if (!en || !ru) return ru;
    static std::unordered_map<std::string, const char*> m;
    if (m.empty()) for (auto& p : kPairs) m[p[0]] = p[1];
    auto it = m.find(ru);
    return it == m.end() ? ru : it->second;
}
